function IntegrationsCenter(){
 const [data,setData]=useState({items:[]}),[form,setForm]=useState({type:'API'}),[msg,setMsg]=useState(''),[token,setToken]=useState('');async function load(){const r=await fetch('/api/admin/integrations');if(r.ok)setData(await r.json())}useEffect(()=>{load()},[]);async function create(){setMsg('Creando…');setToken('');const r=await fetch('/api/admin/integrations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form)}),j=await r.json();setMsg(r.ok?'✓ Integración creada':j.error||'Error');if(r.ok){setToken(j.token);setForm({type:'API'});load()}}async function patch(id,body){const r=await fetch('/api/admin/integrations',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,...body})}),j=await r.json();if(j.token)setToken(j.token);setMsg(r.ok?'✓ Integración actualizada':j.error||'Error');if(r.ok)load()}return <><section className="hero simple"><div><span className="eyebrow">A-NOVA CONNECTOR · ENTERPRISE</span><h1>Integraciones</h1><p>Conecta sistemas escolares, bases de datos y procesos de sincronización mediante un conector seguro.</p></div></section><section className="box"><div className="sectionTitle"><div><span className="eyebrow">NUEVA FUENTE</span><h2>Conector de alumnos</h2></div><span className="tag">MULTI-TENANT</span></div><div className="adminForm"><input placeholder="Nombre · SIS Escolar" value={form.name||''} onChange={e=>setForm({...form,name:e.target.value})}/><select value={form.type} onChange={e=>setForm({...form,type:e.target.value})}><option value="API">API / Connector</option><option value="SQLSERVER">SQL Server</option><option value="MYSQL">MySQL</option><option value="POSTGRESQL">PostgreSQL</option><option value="CSV">CSV</option><option value="SIS">SIS externo</option></select><input placeholder="URL del sistema (opcional)" value={form.baseUrl||''} onChange={e=>setForm({...form,baseUrl:e.target.value})}/><button onClick={create}>+ Crear integración</button></div>{msg&&<p className="adminMsg">{msg}</p>}{token&&<div className="tokenBox"><b>Token generado · cópialo ahora</b><code>{token}</code><small>No se volverá a mostrar. El conector debe enviarlo como Bearer token a <b>POST /api/integrations/push</b>.</small></div>}<div className="integrationList">{data.items.map(x=><article key={x.id}><div><span className="eyebrow">{x.type}</span><h3>{x.name}</h3><p>{x.baseUrl||'A-NOVA Connector / Push API'}</p><small>{x.lastSyncAt?`Última sincronización ${new Date(x.lastSyncAt).toLocaleString('es-MX')}`:'Sin sincronizaciones todavía'} · token {x.tokenPrefix||'—'}…</small></div><div><span className={`statusBadge ${x.status==='ACTIVE'?'active':'inactive'}`}>{x.status}</span><button className="secondaryBtn" onClick={()=>patch(x.id,{action:'REGENERATE_TOKEN'})}>Rotar token</button><button onClick={()=>patch(x.id,{status:x.status==='ACTIVE'?'INACTIVE':'ACTIVE'})}>{x.status==='ACTIVE'?'Desactivar':'Activar'}</button></div>{x.syncRuns?.length>0&&<div className="syncHistory">{x.syncRuns.slice(0,3).map(r=><small key={r.id}>{new Date(r.startedAt).toLocaleString('es-MX')} · {r.status} · {r.received} recibidos · {r.created} nuevos · {r.updated} actualizados</small>)}</div>}</article>)}{!data.items.length&&<p>No hay integraciones configuradas.</p>}</div></section></>}

