function TeacherModule({page}){const [data,setData]=useState(null),[selected,setSelected]=useState(''),[msg,setMsg]=useState(''),[period,setPeriod]=useState(1),[date,setDate]=useState(()=>new Date().toISOString().slice(0,10)),[task,setTask]=useState({title:'',description:'',dueDate:'',maxScore:''});async function load(){const r=await fetch('/api/teacher/data');if(r.ok){const j=await r.json();setData(j);setSelected(x=>x||j.assignments?.[0]?.id||'')}}useEffect(()=>{load()},[page]);if(!data)return <section className="box"><p>Cargando portal docente…</p></section>;const a=data.assignments.find(x=>x.id===selected)||data.assignments[0];const pick=<select className="teacherSelect" value={a?.id||''} onChange={e=>setSelected(e.target.value)}>{data.assignments.map(x=><option key={x.id} value={x.id}>{x.subject.name} · {x.group.label}</option>)}</select>;async function post(url,body){setMsg('Guardando…');const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json();setMsg(r.ok?'✓ Guardado correctamente':j.error||'Ocurrió un error');if(r.ok)await load()}if(page==='Mis grupos'||page==='Materias')return <><section className="hero simple"><div><span className="eyebrow">PORTAL DOCENTE</span><h1>{page}</h1><p>Grupos y materias asignados por Control Escolar.</p></div></section><section className="box"><div className="teacherCards">{data.assignments.map(x=><article key={x.id}><span className="eyebrow">{x.subject.code} · {x.group.cycle}</span><h2>{x.subject.name}</h2><b>{x.group.label}</b><p>{x.students.length} alumnos · Aula {x.group.room||'por definir'}</p></article>)}</div></section></>;if(page==='Calificaciones')return <><section className="hero simple"><div><span className="eyebrow">EVALUACIÓN</span><h1>Calificaciones</h1><p>Captura calificaciones por periodo. Escala de 0 a 10.</p></div></section><section className="box"><div className="teacherToolbar">{pick}<select value={period} onChange={e=>setPeriod(Number(e.target.value))}>{(a?.group.periods||[]).map(p=><option key={p.id} value={p.number}>{p.name}{p.open?"":" · Cerrado"}</option>)}</select></div>{msg&&<p className="adminMsg">{msg}</p>}<div className="gradeTable">{a?.students.map(st=>{const g=a.grades.find(g=>g.studentId===st.id&&g.period===period);return <GradeRow key={st.id} st={st} initial={g?.score??''} save={score=>post('/api/teacher/grades',{assignmentId:a.id,studentId:st.id,period,score})}/>})}</div></section></>;if(page==='Asistencia')return <><section className="hero simple"><div><span className="eyebrow">CONTROL DE ASISTENCIA</span><h1>Pasar lista</h1><p>Registra presente, falta, retardo o falta justificada.</p></div></section><section className="box"><div className="teacherToolbar">{pick}<input type="date" value={date} onChange={e=>setDate(e.target.value)}/></div>{msg&&<p className="adminMsg">{msg}</p>}<div className="gradeTable">{a?.students.map(st=>{const existing=a.attendance.find(x=>x.studentId===st.id&&String(x.date).slice(0,10)===date);return <div className="gradeRow" key={st.id}><div><b>{st.firstName} {st.lastName}</b><small>{st.studentCode||st.email}</small></div><select defaultValue={existing?.status||'PRESENT'} onChange={e=>post('/api/teacher/attendance',{assignmentId:a.id,studentId:st.id,date,status:e.target.value})}><option value="PRESENT">Presente</option><option value="ABSENT">Falta</option><option value="LATE">Retardo</option><option value="JUSTIFIED">Justificada</option></select></div>})}</div></section></>;if(page==='Tareas')return <TeacherAssignments a={a} pick={pick} reload={load}/>;if(page==='Evaluaciones')return <ExamCenter role="Profesor"/>;if(page==='Reportes')return <EnterpriseReports/>;if(page==='Incidencias')return <TeacherReports data={data}/>;return <Generic role="Profesor" page={page} data={data}/>}
function GradeRow({st,initial,save}){const [v,setV]=useState(initial);return <div className="gradeRow"><div><b>{st.firstName} {st.lastName}</b><small>{st.studentCode||st.email}</small></div><input type="number" min="0" max="10" step=".1" value={v} onChange={e=>setV(e.target.value)} placeholder="—"/><button onClick={()=>save(v)}>Guardar</button></div>}

function ScheduleList({items=[]}){const days=['','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'];if(!items.length)return <p>No hay horarios configurados todavía.</p>;return <div className="studentList">{items.map(h=><div className="studentLine" key={h.id}><div><b>{h.subject}{h.group?` · ${h.group}`:''}</b><small>{days[h.dayOfWeek]} · {h.startTime}–{h.endTime} · {h.room||'Aula por definir'}{h.teacher?` · ${h.teacher}`:''}</small></div><span className="countPill">{days[h.dayOfWeek]}</span></div>)}</div>}
function IncidentList({items=[],admin=false,onStatus}){if(!items.length)return <p>No hay reportes registrados.</p>;return <div className="studentList">{items.map(i=><div className="studentLine incidentLine" key={i.id}><div><b>{i.category}{i.student?` · ${i.student.firstName} ${i.student.lastName}`:''}</b><small>{new Date(i.occurredAt).toLocaleDateString('es-MX')} · {i.reporterName||`${i.reporter?.firstName||''} ${i.reporter?.lastName||''}`} · {i.severity}</small><p>{i.description}</p></div>{admin?<select className="miniSelect" value={i.status} onChange={e=>onStatus(i.id,e.target.value)}><option value="OPEN">Abierto</option><option value="IN_REVIEW">En revisión</option><option value="CLOSED">Cerrado</option></select>:<span className="countPill">{{OPEN:'Abierto',IN_REVIEW:'En revisión',CLOSED:'Cerrado'}[i.status]||i.status}</span>}</div>)}</div>}
function TeacherReports({data}){const [assignmentId,setAssignmentId]=useState(data.assignments?.[0]?.id||'');const [studentId,setStudentId]=useState('');const [category,setCategory]=useState('Académica');const [severity,setSeverity]=useState('LOW');const [description,setDescription]=useState('');const [items,setItems]=useState([]);const [msg,setMsg]=useState('');const a=data.assignments.find(x=>x.id===assignmentId)||data.assignments[0];useEffect(()=>{fetch('/api/teacher/incidents').then(r=>r.ok?r.json():[]).then(setItems)},[]);async function save(){setMsg('Guardando…');const r=await fetch('/api/teacher/incidents',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({studentId,category,severity,description})});const j=await r.json();if(!r.ok){setMsg(j.error||'Error');return}setMsg('✓ Reporte registrado');setDescription('');setStudentId('');const rr=await fetch('/api/teacher/incidents');if(rr.ok)setItems(await rr.json())}return <><section className="hero simple"><div><span className="eyebrow">SEGUIMIENTO</span><h1>Reportes</h1><p>Registra incidencias de alumnos pertenecientes a tus grupos.</p></div></section><section className="box"><div className="adminForm"><select value={assignmentId} onChange={e=>{setAssignmentId(e.target.value);setStudentId('')}}>{data.assignments.map(x=><option key={x.id} value={x.id}>{x.subject.name} · {x.group.label}</option>)}</select><select value={studentId} onChange={e=>setStudentId(e.target.value)}><option value="">Alumno</option>{(a?.students||[]).map(st=><option key={st.id} value={st.id}>{st.firstName} {st.lastName}</option>)}</select><select value={category} onChange={e=>setCategory(e.target.value)}><option>Académica</option><option>Disciplina</option><option>Convivencia</option><option>Reconocimiento</option></select><select value={severity} onChange={e=>setSeverity(e.target.value)}><option value="LOW">Leve</option><option value="MEDIUM">Media</option><option value="HIGH">Alta</option></select><input placeholder="Descripción" value={description} onChange={e=>setDescription(e.target.value)}/><button onClick={save}>+ Registrar</button></div>{msg&&<p className="adminMsg">{msg}</p>}<IncidentList items={items}/></section></>}
function AdminDocuments({students}){const [studentId,setStudentId]=useState(students?.[0]?.id||'');const st=students.find(x=>x.id===studentId);return <><section className="hero simple"><div><span className="eyebrow">CONTROL ESCOLAR · DOCUMENTOS</span><h1>Boletas académicas</h1><p>Genera documentos únicamente para alumnos de esta escuela.</p></div></section><section className="box"><div className="adminForm"><label>Alumno<select value={studentId} onChange={e=>setStudentId(e.target.value)}>{students.map(x=><option key={x.id} value={x.id}>{x.firstName} {x.lastName} · {x.studentCode||'Sin matrícula'}</option>)}</select></label></div></section>{studentId&&<AcademicDocuments studentId={studentId} studentName={st?`${st.firstName} ${st.lastName}`:''}/>}</>}

function AdminModule({page,onChanged}){const [data,setData]=useState(null),[msg,setMsg]=useState(''),[form,setForm]=useState({role:'STUDENT',active:false}),[search,setSearch]=useState(''),[roleFilter,setRoleFilter]=useState('ALL'),[editing,setEditing]=useState(null);async function load(){const r=await fetch('/api/admin/data');if(r.ok)setData(await r.json())}useEffect(()=>{load()},[page]);async function send(url,body,method='POST'){setMsg('Guardando…');const r=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json();setMsg(r.ok?'✓ Cambios guardados':j.error||'Ocurrió un error');if(r.ok){setForm({role:'STUDENT',active:false});await load();onChanged?.()}}if(!data)return <section className="box"><p>Cargando gestión escolar…</p></section>;
 const teachers=data.users.filter(x=>x.role==='TEACHER'&&x.status==='ACTIVE');
 if(page==='Reportes')return <EnterpriseReports/>;
 if(page==='Auditoría')return <AuditCenter/>;
 if(page==='Configuración')return <BrandingSettings/>;
 if(page==='Integraciones')return <IntegrationsCenter/>;
 if(page==='Seguridad')return <SecurityCenter/>;
 if(page==='Licencia')return <LicenseCenter/>;
 if(page==='Documentos'){const students=data.users.filter(x=>x.role==='STUDENT'&&x.status==='ACTIVE');return <AdminDocuments students={students}/>;}
 if(page==='Usuarios'){
  const roleLabel={STUDENT:'Alumno',TEACHER:'Profesor',ADMIN:'Administrador',TUTOR:'Tutor'};
  const statusLabel={ACTIVE:'Activo',INACTIVE:'Inactivo',SUSPENDED:'Suspendido'};
  const visible=data.users.filter(u=>{const q=search.toLowerCase().trim();const matches=!q||`${u.firstName} ${u.lastName} ${u.email} ${u.studentCode||''} ${u.employeeCode||''}`.toLowerCase().includes(q);return matches&&(roleFilter==='ALL'||u.role===roleFilter)});
  const beginEdit=u=>setEditing({id:u.id,firstName:u.firstName,lastName:u.lastName,email:u.email,role:u.role,code:u.studentCode||u.employeeCode||'',groupId:u.enrollments?.[0]?.groupId||'',password:''});
  const saveEdit=async()=>{setMsg('Guardando…');const r=await fetch('/api/admin/users',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(editing)});const j=await r.json();setMsg(r.ok?'✓ Usuario actualizado':j.error||'Ocurrió un error');if(r.ok){setEditing(null);await load();onChanged?.()}};
  return <><section className="hero simple"><div><span className="eyebrow">ADMINISTRACIÓN · FASE 2</span><h1>Usuarios</h1><p>Alta, edición, búsqueda y control de alumnos, profesores y administradores.</p></div></section>
  <section className="box"><div className="sectionTitle"><div><span className="eyebrow">ALTA DE CUENTAS</span><h2>Nuevo usuario</h2></div><span className="countPill">{data.users.length} usuarios</span></div><div className="adminForm"><input placeholder="Nombre" value={form.firstName||''} onChange={e=>setForm({...form,firstName:e.target.value})}/><input placeholder="Apellidos" value={form.lastName||''} onChange={e=>setForm({...form,lastName:e.target.value})}/><input placeholder="Correo institucional" value={form.email||''} onChange={e=>setForm({...form,email:e.target.value})}/><select value={form.role} onChange={e=>setForm({...form,role:e.target.value,groupId:''})}><option value="STUDENT">Alumno</option><option value="TEACHER">Profesor</option><option value="ADMIN">Administrador</option><option value="TUTOR">Tutor</option></select><input placeholder={form.role==='STUDENT'?'Matrícula':'No. empleado'} value={form.code||''} onChange={e=>setForm({...form,code:e.target.value})}/>{form.role==='STUDENT'&&<select value={form.groupId||''} onChange={e=>setForm({...form,groupId:e.target.value})}><option value="">Sin grupo por ahora</option>{data.groups.filter(g=>g.active).map(g=><option key={g.id} value={g.id}>{g.grade}° {g.name} · {g.cycle.name}</option>)}</select>}<input type="password" placeholder="Contraseña temporal (opcional)" value={form.password||''} onChange={e=>setForm({...form,password:e.target.value})}/><button onClick={()=>send('/api/admin/users',form)}>+ Crear usuario</button></div><p className="formHint">Si no defines contraseña temporal, A-NOVA asignará la contraseña inicial configurada para el MVP. Podrás cambiarla después desde edición.</p>{msg&&<p className="adminMsg">{msg}</p>}</section>
  <section className="box userListBox"><div className="sectionTitle"><div><span className="eyebrow">DIRECTORIO</span><h2>Usuarios registrados</h2></div></div><div className="userTools"><input placeholder="Buscar por nombre, correo o matrícula…" value={search} onChange={e=>setSearch(e.target.value)}/><select value={roleFilter} onChange={e=>setRoleFilter(e.target.value)}><option value="ALL">Todos los roles</option><option value="STUDENT">Alumnos</option><option value="TEACHER">Profesores</option><option value="ADMIN">Administradores</option></select></div><div className="adminTable">{visible.map(u=><div className={`adminRow userRow ${u.status!=='ACTIVE'?'mutedRow':''}`} key={u.id}><div className="userIdentity"><b>{u.firstName} {u.lastName}</b><span>{u.email}</span><small>{roleLabel[u.role]||u.role}{u.studentCode?` · Matrícula ${u.studentCode}`:''}{u.employeeCode?` · No. empleado ${u.employeeCode}`:''}{u.enrollments?.[0]?.group?` · ${u.enrollments[0].group.grade}° ${u.enrollments[0].group.name}`:''}</small></div><span className={`statusBadge ${u.status.toLowerCase()}`}>{statusLabel[u.status]||u.status}</span><div className="rowActions"><button className="secondaryBtn" onClick={()=>beginEdit(u)}>Editar</button><button onClick={()=>send('/api/admin/users',{id:u.id,status:u.status==='ACTIVE'?'INACTIVE':'ACTIVE'},'PATCH')}>{u.status==='ACTIVE'?'Desactivar':'Activar'}</button></div></div>)}{visible.length===0&&<div className="noResults">No encontramos usuarios con esos filtros.</div>}</div></section>
  {editing&&<div className="modalBack" onClick={()=>setEditing(null)}><div className="editModal" onClick={e=>e.stopPropagation()}><div className="sectionTitle"><div><span className="eyebrow">EDITAR CUENTA</span><h2>{editing.firstName} {editing.lastName}</h2></div><button className="closeBtn" onClick={()=>setEditing(null)}>×</button></div><div className="editGrid"><label>Nombre<input value={editing.firstName} onChange={e=>setEditing({...editing,firstName:e.target.value})}/></label><label>Apellidos<input value={editing.lastName} onChange={e=>setEditing({...editing,lastName:e.target.value})}/></label><label>Correo institucional<input value={editing.email} onChange={e=>setEditing({...editing,email:e.target.value})}/></label><label>Rol<select value={editing.role} onChange={e=>setEditing({...editing,role:e.target.value,groupId:''})}><option value="STUDENT">Alumno</option><option value="TEACHER">Profesor</option><option value="ADMIN">Administrador</option><option value="TUTOR">Tutor</option></select></label><label>{editing.role==='STUDENT'?'Matrícula':'No. empleado'}<input value={editing.code||''} onChange={e=>setEditing({...editing,code:e.target.value})}/></label>{editing.role==='STUDENT'&&<label>Grupo<select value={editing.groupId||''} onChange={e=>setEditing({...editing,groupId:e.target.value})}><option value="">Sin grupo</option>{data.groups.filter(g=>g.active).map(g=><option key={g.id} value={g.id}>{g.grade}° {g.name} · {g.cycle.name}</option>)}</select></label>}<label className="fullField">Nueva contraseña <span>(dejar vacío para conservarla)</span><input type="password" value={editing.password||''} onChange={e=>setEditing({...editing,password:e.target.value})} placeholder="Mínimo 8 caracteres"/></label></div><div className="modalActions"><button className="secondaryBtn" onClick={()=>setEditing(null)}>Cancelar</button><button onClick={saveEdit}>Guardar cambios</button></div></div></div>}</>;
 }
 if(page==='Tutores'){const tutors=data.users.filter(x=>x.role==='TUTOR'),students=data.users.filter(x=>x.role==='STUDENT');return <><section className="hero simple"><div><span className="eyebrow">PORTAL FAMILIAR</span><h1>Tutores y vínculos</h1><p>Vincula cada cuenta de tutor únicamente con los alumnos que puede consultar.</p></div></section><section className="box"><div className="adminForm"><select value={form.guardianId||''} onChange={e=>setForm({...form,guardianId:e.target.value})}><option value="">Selecciona tutor</option>{tutors.map(x=><option key={x.id} value={x.id}>{x.firstName} {x.lastName}</option>)}</select><select value={form.studentId||''} onChange={e=>setForm({...form,studentId:e.target.value})}><option value="">Selecciona alumno</option>{students.map(x=><option key={x.id} value={x.id}>{x.firstName} {x.lastName} · {x.studentCode||'Sin matrícula'}</option>)}</select><button onClick={()=>send('/api/admin/guardians',{guardianId:form.guardianId,studentId:form.studentId})}>+ Vincular</button></div>{msg&&<p className="adminMsg">{msg}</p>}<div className="adminTable">{tutors.map(t=><div className="adminRow" key={t.id}><div><b>{t.firstName} {t.lastName}</b><span>{t.email} · {(t.guardianOf||[]).length} alumno(s) vinculado(s)</span>{(t.guardianOf||[]).map(r=><small key={r.student.id}>{r.student.firstName} {r.student.lastName} · {r.student.studentCode||'Sin matrícula'}</small>)}</div></div>)}{!tutors.length&&<p>Crea una cuenta con rol Tutor desde Usuarios.</p>}</div></section></>}
 if(page==='Materias')return <><section className="hero simple"><div><span className="eyebrow">PLAN ACADÉMICO</span><h1>Materias</h1><p>Crea y administra el catálogo académico.</p></div></section><section className="box"><div className="adminForm"><input placeholder="Código (MAT)" value={form.code||''} onChange={e=>setForm({...form,code:e.target.value})}/><input placeholder="Nombre de la materia" value={form.name||''} onChange={e=>setForm({...form,name:e.target.value})}/><button onClick={()=>send('/api/admin/subjects',form)}>+ Nueva materia</button></div>{msg&&<p className="adminMsg">{msg}</p>}<div className="adminTable">{data.subjects.map(x=><div className="adminRow" key={x.id}><div><b>{x.name}</b><span>{x.code}</span></div><button onClick={()=>send('/api/admin/subjects',{id:x.id,active:!x.active},'PATCH')}>{x.active?'Desactivar':'Activar'}</button></div>)}</div></section></>;
 if(page==='Ciclos escolares')return <><section className="hero simple"><div><span className="eyebrow">CONFIGURACIÓN</span><h1>Ciclos escolares</h1><p>Define los periodos de operación de la escuela.</p></div></section><section className="box"><div className="adminForm"><input placeholder="2027–2028" value={form.name||''} onChange={e=>setForm({...form,name:e.target.value})}/><input type="date" value={form.startDate||''} onChange={e=>setForm({...form,startDate:e.target.value})}/><input type="date" value={form.endDate||''} onChange={e=>setForm({...form,endDate:e.target.value})}/><label className="check"><input type="checkbox" checked={!!form.active} onChange={e=>setForm({...form,active:e.target.checked})}/> Ciclo activo</label><button onClick={()=>send('/api/admin/cycles',form)}>+ Crear ciclo</button></div>{msg&&<p className="adminMsg">{msg}</p>}<div className="adminTable">{data.cycles.map(x=><div className="adminRow" key={x.id}><div><b>{x.name}</b><span>{x.active?'ACTIVO':'Inactivo'}</span></div></div>)}</div></section></>;
 if(page==='Grupos')return <><section className="hero simple"><div><span className="eyebrow">CONTROL ESCOLAR</span><h1>Grupos</h1><p>Organiza alumnos por grado, grupo y ciclo.</p></div></section><section className="box"><div className="adminForm"><select value={form.cycleId||''} onChange={e=>setForm({...form,cycleId:e.target.value})}><option value="">Selecciona ciclo</option>{data.cycles.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select><input type="number" min="1" placeholder="Grado" value={form.grade||''} onChange={e=>setForm({...form,grade:e.target.value})}/><input placeholder="Grupo (A)" value={form.name||''} onChange={e=>setForm({...form,name:e.target.value})}/><input placeholder="Salón" value={form.room||''} onChange={e=>setForm({...form,room:e.target.value})}/><button onClick={()=>send('/api/admin/groups',form)}>+ Crear grupo</button></div>{msg&&<p className="adminMsg">{msg}</p>}<div className="adminTable">{data.groups.map(g=><div className="adminRow" key={g.id}><div><b>{g.grade}° {g.name}</b><span>{g.cycle.name} · {g.room||'Sin salón'} · {g._count.enrollments} alumnos</span></div></div>)}</div></section></>;
 if(page==='Asignaciones')return <><section className="hero simple"><div><span className="eyebrow">DOCENCIA</span><h1>Asignaciones</h1><p>Vincula profesor, materia y grupo.</p></div></section><section className="box"><div className="adminForm"><select value={form.teacherId||''} onChange={e=>setForm({...form,teacherId:e.target.value})}><option value="">Profesor</option>{teachers.map(x=><option key={x.id} value={x.id}>{x.firstName} {x.lastName}</option>)}</select><select value={form.subjectId||''} onChange={e=>setForm({...form,subjectId:e.target.value})}><option value="">Materia</option>{data.subjects.filter(x=>x.active).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select><select value={form.groupId||''} onChange={e=>setForm({...form,groupId:e.target.value})}><option value="">Grupo</option>{data.groups.filter(x=>x.active).map(g=><option key={g.id} value={g.id}>{g.grade}° {g.name} · {g.cycle.name}</option>)}</select><button onClick={()=>send('/api/admin/assignments',form)}>+ Asignar</button></div>{msg&&<p className="adminMsg">{msg}</p>}<div className="adminTable">{data.assignments.map(x=><div className="adminRow" key={x.id}><div><b>{x.subject.name} · {x.group.grade}° {x.group.name}</b><span>{x.teacher.firstName} {x.teacher.lastName} · {x.group.cycle.name}</span></div></div>)}</div></section></>;
 return <Generic role="Administrador" page={page}/>}

export default function Home(){const [role,setRole]=useState(null);const [notificationCount,setNotificationCount]=useState(0);const [page,setPage]=useState('Inicio');const [refreshKey,setRefreshKey]=useState(0);const [academic,setAcademic]=useState(null);const [branding,setBranding]=useState(baseBrand);const [checking,setChecking]=useState(true);const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [error,setError]=useState('');const [loading,setLoading]=useState(false);
 const roleMap={STUDENT:'Alumno',TEACHER:'Profesor',ADMIN:'Administrador',TUTOR:'Tutor'};
 async function loadBranding(){try{const code=typeof window!=='undefined'?new URLSearchParams(window.location.search).get('school'):'';const r=await fetch(`/api/branding${code?`?code=${encodeURIComponent(code)}`:''}`);if(r.ok)setBranding({...baseBrand,...await r.json()})}catch{}}
 async function loadAcademic(){const r=await fetch('/api/academic/dashboard');if(r.ok)setAcademic(await r.json());const n=await fetch('/api/notifications');if(n.ok){const j=await n.json();setNotificationCount(j.unread||0)}}
 useEffect(()=>{const onBrand=e=>setBranding({...baseBrand,...e.detail});window.addEventListener('anova-branding',onBrand);(async()=>{try{await loadBranding();const r=await fetch('/api/auth/me');if(r.ok){const j=await r.json();setRole(roleMap[j.user.role]);await loadAcademic();await loadBranding()}}finally{setChecking(false)}})();return()=>window.removeEventListener('anova-branding',onBrand)},[]);
 useEffect(()=>{if(typeof document==='undefined')return;document.title=`${branding.displayName||'Colegio Simón Bolívar del Pedregal'} · Portal Académico`;if(branding.logoUrl){let link=document.querySelector("link[rel='icon']");if(!link){link=document.createElement('link');link.rel='icon';document.head.appendChild(link)}link.href=branding.logoUrl}},[branding]);
 async function login(e){e.preventDefault();setLoading(true);setError('');try{const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})});const j=await r.json();if(!r.ok)throw new Error(j.error||'No se pudo iniciar sesión.');setRole(roleMap[j.user.role]);setPage('Inicio');await loadAcademic();await loadBranding()}catch(e){setError(e.message)}finally{setLoading(false)}}
 async function logout(){await fetch('/api/auth/logout',{method:'POST'});setAcademic(null);setRole(null);setEmail('');setPassword('');setPage('Inicio')}
 const brandName=branding.displayName||'Colegio Simón Bolívar del Pedregal',brandShort=branding.shortName||'CSB Pedregal',brandStyle={'--brandPrimary':branding.primaryColor||'#670337','--brandSecondary':branding.secondaryColor||'#02244A','--brandAccent':branding.accentColor||'#D4AD22'};
 if(checking)return <main className="login" style={brandStyle}><section className="brand"><BrandLogo branding={branding}/><div className="wordmark">{brandShort}<small>{branding.showPoweredBy!==false?'POWERED BY A-NOVA':'SCHOOL'}</small></div></section><section className="loginSide"><div className="loginCard"><span className="eyebrow">{brandShort}</span><h2>Preparando tu sesión…</h2></div></section></main>;
 if(!role)return <main className="login" style={brandStyle}><section className="brand"><BrandLogo branding={branding}/><div className="wordmark">{brandShort}<small>{branding.showPoweredBy!==false?'POWERED BY A-NOVA':'SCHOOL'}</small></div><div className="brandCopy"><span className="eyebrow">PORTAL ACADÉMICO CSB</span><h1>{brandName}</h1><p>Formar para construir un mundo fraterno.</p></div><footer>© 2026 {brandName} · Powered by A-NOVA · CSB Edition</footer></section><section className="loginSide"><form className="loginCard" onSubmit={login}><span className="eyebrow">COLEGIO SIMÓN BOLÍVAR DEL PEDREGAL</span><h2>Portal Académico</h2><p>Ingresa con tu cuenta institucional para continuar.</p><label>Correo institucional</label><input value={email} onChange={e=>setEmail(e.target.value)} placeholder="correo institucional" autoComplete="email" required/><label>Contraseña</label><input value={password} onChange={e=>setPassword(e.target.value)} type="password" placeholder="••••••••" autoComplete="current-password" required minLength={8}/>{error&&<p style={{color:'#ff8b8b',marginTop:12}}>{error}</p>}<button type="submit" disabled={loading||!email||password.length<8} style={{width:'100%',marginTop:18,padding:'14px 18px',borderRadius:12,border:0,fontWeight:700,cursor:'pointer'}}>{loading?'Verificando…':'Entrar →'}</button><div className="demoLabel">CUENTAS DE PRUEBA</div><div style={{fontSize:12,lineHeight:1.8,opacity:.75}}>andre@anova.edu.mx · Alumno<br/>edgar@anova.edu.mx · Profesor<br/>admin@anova.edu.mx · Administrador<br/><b>Contraseña: Nova2026!</b></div><div className="secure">◈ &nbsp; CSB PEDREGAL · POWERED BY A-NOVA · v0.5.1</div></form></section></main>;
 const d=roles[role];let body=page==='Intelligence'?<IntelligenceDashboard role={role}/>:page==='Notificaciones'?<Notifications onCount={setNotificationCount}/>:page==='Mensajes'?<Messages/>:page==='Inicio'?(role==='Alumno'?<StudentHome data={academic}/>:role==='Profesor'?<ProfessorHome data={academic}/>:role==='Tutor'?<TutorHome data={academic}/>:<AdminHome data={academic}/>):role==='Administrador'?<AdminModule key={page+refreshKey} page={page} onChanged={()=>{loadAcademic();setRefreshKey(x=>x+1)}}/>:role==='Profesor'?<TeacherModule key={page+refreshKey} page={page}/>:role==='Tutor'?<TutorModule page={page} data={academic}/>:role==='Alumno'?<StudentModule page={page} data={academic}/>:<Generic role={role} page={page} data={academic}/>;
 return <main className="app" style={brandStyle}><aside><div className="sideBrand"><BrandLogo branding={branding} small/><div><b>{brandShort}</b><span>{branding.showPoweredBy!==false?'POWERED BY A-NOVA':'SCHOOL'}</span></div></div><div className="cycle"><span>CICLO ESCOLAR</span><b>{academic?.cycle||'2026 — 2027'}</b></div><nav>{d.menu.map(x=><button className={page===x?'active':''} onClick={()=>setPage(x)} key={x}><Icon name={x}/>{x}</button>)}</nav><div className="userBox"><div className="avatar">{academic?.user?`${academic.user.firstName?.[0]||''}${academic.user.lastName?.[0]||''}`.toUpperCase():d.initials}</div><div><b>{academic?.user?`${academic.user.firstName} ${academic.user.lastName}`:d.name}</b><span>{d.subtitle}</span></div><button onClick={logout}>↪</button></div></aside><section className="content"><div className="topbar"><span>{page}</span><div><button>⌕</button><button onClick={()=>setPage('Notificaciones')} className="bellBtn">♢{notificationCount>0&&<i>{notificationCount>99?'99+':notificationCount}</i>}</button></div></div>{body}<footer className="appFoot">{brandName.toUpperCase()} · PORTAL ACADÉMICO CSB · POWERED BY A-NOVA · v0.5.1</footer></section></main>}
